Problem:
An airport can transport travelers using commercial planes and private planes. A commercial plane can carry 180 travelers while a private plane can carry 30 travelers. Because the destination is more remote, there are few airport runways. Therefore, there must be twice as many private planes as commercial planes. If the airport needs to transport at least 3500 travelers, how many of each type of planes should be used to minimize the total number of planes used.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "commercial planes",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "private planes",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "commercial planes",
     "coef": 1.0
    },
    {
     "var": "private planes",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "travelers",
    "terms": [
     {
      "var": "commercial planes",
      "coef": 180.0
     },
     {
      "var": "private planes",
      "coef": 30.0
     }
    ],
    "sense": ">=",
    "rhs": 3500.0
   },
   {
    "name": "private to commercial ratio",
    "terms": [
     {
      "var": "private planes",
      "coef": 1.0
     },
     {
      "var": "commercial planes",
      "coef": -2.0
     }
    ],
    "sense": "==",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 45.0,
  "values": {
   "commercial planes": 15.0,
   "private planes": 30.0
  },
  "binding": [
   "private to commercial ratio"
  ],
  "slack": {
   "travelers": 100.0,
   "private to commercial ratio": 0.0
  },
  "shadow_prices": null,
  "limits": {
   "travelers": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "private to commercial ratio": {
    "dropped_improves": true,
    "loosened_improves": null
   }
  }
 }
}
